mapper.select:

        select * from (select temp_data.*,
        tmpTable.hasFlow from (

            /*流程中*/
            /*计划类净值除权*/
            SELECT
            #{PAGE_DATE_STATUS03} statusValid,

            tpd.WORKFLOW_ID workflowId
            from
            WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where

            tpd.PS=#{PS_T13}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and tpd.TRADE_DATE >= #{exRightsDateStart}
	            and tpd.TRADE_DATE <= #{exRightsDateEnd}

            /*计划类净值现金分红*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS03} statusValid,

            tpd.WORKFLOW_ID workflowId
            from
            WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where

            tpd.PS=#{PS_T11}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and btrd.TRADE_DATE >= #{exRightsDateStart}
	            and btrd.TRADE_DATE <= #{exRightsDateEnd}

            /*计划类净值红利再投*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS03} statusValid,

            tpd.WORKFLOW_ID workflowId
            from
            WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where

            tpd.PS=#{PS_T12}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and btrd.TRADE_DATE >= #{exRightsDateStart}
	            and btrd.TRADE_DATE <= #{exRightsDateEnd}





                UNION ALL

            /*计划类净值除权*/
            SELECT
            #{PAGE_DATE_STATUS05} statusValid,

            null workflowId
            from
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where
            tpd.PS=#{PS_T13}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and tpd.TRADE_DATE >= #{exRightsDateStart}
	            and tpd.TRADE_DATE <= #{exRightsDateEnd}

            /*净值现金分红*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS05} statusValid,

            null workflowId
            from
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where
            /*交易方向现金分红*/
            tpd.PS=#{PS_T11}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and btrd.TRADE_DATE >= #{exRightsDateStart}
	            and btrd.TRADE_DATE <= #{exRightsDateEnd}

            /*非货红利再投*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS05} statusValid,

            null workflowId
            from
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where
            /*交易方向红利再投*/
            tpd.PS=#{PS_T12}
            and tpd.TRADE_STATUS = #{TRADE_STATUS01}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and btrd.TRADE_DATE >= #{exRightsDateStart}
	            and btrd.TRADE_DATE <= #{exRightsDateEnd}


        /*撤销数据*/


                UNION ALL

            /*计划类净值除权*/
            SELECT
            #{PAGE_DATE_STATUS06} statusValid,

            null workflowId
            FROM
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            where
            tpd.PS=#{PS_T13}
            and tpd.TRADE_STATUS = #{TRADE_STATUS03}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and tpd.TRADE_DATE >= #{exRightsDateStart}
	            and tpd.TRADE_DATE <= #{exRightsDateEnd}

            /*计划类净值现金分红*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS06} statusValid,

            null workflowId
            FROM
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            /*交易方向现金分红*/
            where
            tpd.PS=#{PS_T11}
            and tpd.TRADE_STATUS = #{TRADE_STATUS03}
            and tpd.IS_CANCEL = #{YESNO_N}



	            and btrd.TRADE_DATE >= #{exRightsDateStart}
	            and btrd.TRADE_DATE <= #{exRightsDateEnd}

            /*计划类净值红利再投*/
            UNION ALL
            SELECT
            #{PAGE_DATE_STATUS06} statusValid,

            null workflowId
            FROM
            TRD_FIN_PRODUCT_DEAL_TOTAL tpd

            /*交易方向红利再投*/
            where
            tpd.PS=#{PS_T12}
